import 'dart:convert';import 'package:shared_preferences/shared_preferences.dart';import '../domain/repository_source.dart';import '../domain/repository_storage.dart';
class SharedPreferencesRepositoryStorage implements RepositoryStorage{const SharedPreferencesRepositoryStorage();static const _key='addko.repository_sources.v1';@override Future<List<RepositorySource>> load() async {final p=await SharedPreferences.getInstance();final raw=p.getString(_key);if(raw==null||raw.trim().isEmpty)return const [];final d=jsonDecode(raw);if(d is! List)return const [];final r=<RepositorySource>[];for(final e in d){if(e is! Map)continue;try{r.add(RepositorySource.fromJson(Map<String,Object?>.from(e)));}on FormatException{}}return List.unmodifiable(r);}@override Future<void> save(List<RepositorySource> s) async {final p=await SharedPreferences.getInstance();await p.setString(_key,jsonEncode(s.map((e)=>e.toJson()).toList(growable:false)));}}
